from typing import List

def string_to_binary(s: str) -> List[str]:
    """ Convert a single bit string to list of bits. """
    return list(map(lambda x: str(int(x) % 2), s))

def binary_xor(a: List[str], b: List[str]) -> List[str]:
    """ Perform XOR on two lists of bits and return result as a list. """
    return list(map(lambda x, y: '0' if (x == '0' and y == '0') else ('1' if (x != '0' and y != '0') else '0'), a, b))

def list_to_string(l: List[str]) -> str:
    """ Convert a list of bits to a single bit string. """
    return ''.join(l)

def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    """
    a_binary = list_to_binary(a)
    b_binary = list_to_binary(b)
    xor_binary = binary_xor(a_binary, b_binary)
    return list_to_string(xor_binary)

if __name__ == '__main__':
    print(string_xor('010', '110'))
